    Object computeBinaryValue(Object obj1, Token operation, Object obj2) {
        if (!(obj1 instanceof Long && obj2 instanceof Long)) {
            return null;
        }
        Long val1 = (Long) obj1;
        Long val2 = (Long) obj2;

        switch(operation.image) {
          case "<<":
          return val1 << val2;
          case ">>":
          return val1 >> val2;
          case "+":
          return val1 + val2;
          case "-":
          return val1 - val2;
          case "*":
          return val1 * val2;
          case "/":
          return val1 / val2;
          case "%":
          return val1 % val2;
          case "|":
          return val1 | val2;
          case "&":
          return val1 & val2;
          case "^":
          return val1 ^ val2;
          case "==":
          return (val1 == val2 ? 1 : 0);
          case "!=":
          return (val1 != val2 ? 1 : 0);
          case "<":
          return (val1 < val2 ? 1 : 0);
          case ">":
          return (val1 > val2 ? 1 : 0);
          case "<=":
          return (val1 <= val2 ? 1 : 0);
          case ">=":
          return (val1 >= val2 ? 1 : 0);
          case "&&":
          return ((val1 != 0 && val2 != 0) ? 1 : 0);
          case "||":
          return ((val1 != 0 || val2 != 0) ? 1 : 0);
        }
        return null;
    }

    Object computeUnaryValue(Object obj, Token operation) {
        if (!(obj instanceof Long)) {
            return null;
        }
        Long val = (Long) obj;

        switch(operation.image) {
          case "+":
          return val;
          case "-":
          return -val;
          case "~":
          return ~val;
          case "!":
          return (val != 0 ? 0 : 1);
        }
        return null;
    }

    Object computeTernaryValue(Object objTest, Object objTrue, Object objFalse) {
        if (!(objTest instanceof Long)) {
            return null;
        }

        Long testValue = (Long) objTest;
        return (testValue != 0 ? objTrue : objFalse);
    }


